changeSet.sql:
CREATE TABLE payment_gateway_events (
    id          uuid NOT NULL PRIMARY KEY,
    created_at  timestamp(6) with time zone NOT NULL,
    created_by  varchar(255),
    provider    varchar(16) NOT NULL,
    event_type  varchar(64),
    reference   varchar(128),
    raw_body    text NOT NULL
);
CREATE INDEX idx_payment_gateway_events_reference ON payment_gateway_events (reference, created_at);
REVOKE UPDATE, DELETE, TRUNCATE ON payment_gateway_events FROM ${appDbUsername};
COMMENT ON TABLE payment_gateway_events IS
    'Signed payment-gateway webhooks, exactly as received (PY-10). Append-only: the app role cannot update or delete. See AGENTS.md.';
